    source('src-klara-nyreview', 'Portrait of the Robot as a Young Woman', 'Jane Hu, The New York Review of Books, 2021', 'https://www.nybooks.com/articles/2021/11/04/kazuo-ishiguro-klara-robot-woman/', 'secondary_literary_criticism_indexed', 'Public indexed care and Artificial Friend discussion consulted', 'Robotic care and the limits of the human/robot relationship.', 'Public indexed scope only; no paywall access or full novel read. A caregiver and displacement themes do not establish a general distribution system.'),
    source('src-qualityland-automated-futures', 'Peter’s Problem: An Analysis of the Imaginaries about Automated Futures Portrayed in QualityLand', 'Amparo Rosales and Sara Suarez-Gonzalo, De Gruyter Handbook of Automated Futures, 2024', 'https://www.degruyterbrill.com/document/doi/10.1515/9783110792256-003/html', 'secondary_scholarly_chapter_abstract', 'Public abstract and citation read', 'Algorithmic decision-making and personalized automated futures.', 'Abstract only, not the complete chapter. Automated recommendations and ranking do not establish material labor replacement.'),
