    source('src-employees-booker', '2021 International Booker Prize shortlist announcement', 'The Booker Prize Foundation', 'https://thebookerprizes.com/sites/default/files/2021-09/2021%20International%20Booker%20shortlist%20announced%20FINAL%20-%20FOR%20IMMEDIATE%20RELEASE.pdf', 'primary_award_organization_synopsis_indexed', 'Identified public Employees work/crew paragraph read', 'The crew confronts the meaning of continuing work.', 'No PDF rendering or full book read. A workplace allegory does not establish dispensable labor or a post-work material economy.'),
